import pandas as pd

def compute_signal(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy().sort_values(["permno", "time_avail_m"])
    grouped_volume = df.groupby("permno")["mthvol"]
    df["avg_prior_volume"] = (
        grouped_volume.shift(1) + grouped_volume.shift(2) + grouped_volume.shift(3)
    ) / 3
    df["signal"] = 100 * df["avg_prior_volume"] / df["shrout"]
    df["signal"] = df["signal"].replace([float("inf"), float("-inf")], pd.NA)
    df = df[df["signal"].notna() & df["shrout"].notna() & (df["shrout"] != 0)]
    return df[["permno", "time_avail_m", "signal"]].rename(
        columns={"time_avail_m": "yyyymm"}
    )
